["garam","Spice blends","Garam masala (North Indian)","garam","The finishing blend – warm, sweet-aromatic, added at the end of cooking.",[["Cumin (jeera)",25],["Coriander seeds",25],["Black peppercorns",10],["Green cardamom",8],["Black cardamom",4],["Cloves",4],["Cinnamon",8],["Bay leaf",3],["Mace (javitri)",2],["Nutmeg",1],["Dry ginger powder",2]],"Dry-roast all except nutmeg and ginger on low flame 3–4 min till fragrant; cool fully. Grind fine, add nutmeg and ginger, sieve.","Finish dals, paneer gravies, pulao – ½ tsp per kg dish, after the flame is off.","6 months airtight, away from light.",[],"garam masala powder recipe"],
["chaat","Spice blends","Chaat masala","chaat","Tangy, salty, funky – the street-snack seasoning.",[["Cumin, roasted",30],["Coriander seeds",12],["Amchur (dry mango)",20],["Black salt (kala namak)",15],["Dried pomegranate seed (anardana)",5],["Black pepper",5],["Dry ginger",3],["Ajwain",2],["Dried mint",3],["Red chilli powder",3],["Asafoetida",1]],"Roast cumin, coriander, pepper, ajwain, anardana lightly. Cool, grind with the rest. Sieve and mix well.","Fruit chaat, papdi chaat, fries, raita, sliced cucumber, lemon soda.","6 months; the black salt keeps flavour sharp.",[],"chaat masala powder recipe"],
["sambar","South Indian","Sambar powder","sambar","Dark, nutty, hot – the base of every sambar and vegetable kootu.",[["Dried red chilli",25],["Coriander seeds",35],["Chana dal",10],["Toor dal",6],["Cumin",5],["Fenugreek (methi) seed",3],["Black pepper",3],["Mustard seed",2],["Curry leaves, dried",5],["Turmeric powder",4],["Asafoetida",1]],"Dry-roast dals till golden, then each spice separately on low flame. Cool completely, grind in batches to a medium-fine powder.","2 tbsp per litre of sambar; also for vegetable stews and sambar rice.","4–5 months; keep dry.",[],"sambar powder recipe"],
["rasam","South Indian","Rasam powder","sambar","Peppery and cumin-led, for thin, sour rasam.",[["Coriander seeds",30],["Dried red chilli",15],["Black pepper",12],["Cumin",15],["Toor dal",10],["Fenugreek seed",2],["Curry leaves, dried",6],["Turmeric",4],["Asafoetida",1]],"Roast dal and spices on low flame separately; cool; grind coarse-to-fine.","1½ tsp per 2 cups tomato-tamarind rasam; add at the end and froth once.","3–4 months.",[],"rasam powder recipe"],
["pav","Street & snack","Pav bhaji masala","pav","Bold red masala that gives bhaji its colour and tang.",[["Coriander seeds",28],["Cumin",10],["Kashmiri chilli, dried",20],["Fennel seed",6],["Black pepper",4],["Cloves",3],["Green cardamom",3],["Black cardamom",4],["Cinnamon",5],["Amchur",10],["Black salt",5],["Dry ginger",2]],"Dry-roast spices except amchur, salt and ginger. Cool, grind fine, add amchur, salt, ginger.","2–3 tbsp per kg bhaji with butter and lemon at the end.","5–6 months.",[],"pav bhaji masala recipe"],
["chole","Punjabi","Chole masala","chole","Dark, tangy chickpea masala (with tea-bag colouring trick).",[["Coriander seeds",30],["Cumin",12],["Amchur",12],["Anardana",8],["Black pepper",5],["Dry red chilli",8],["Black cardamom",4],["Cloves",3],["Cinnamon",5],["Bay leaf",3],["Black salt",5],["Dry ginger",4],["Dried methi leaves (kasuri)",3]],"Roast whole spices; cool; grind with amchur, black salt, ginger and kasuri methi.","3 tbsp per kg boiled chickpeas; cook with tea-water for dark colour.","5 months.",[],"chole masala powder recipe"],
["kitchenking","Spice blends","Kitchen King masala","garam","All-purpose restaurant blend for paneer and mixed vegetables.",[["Coriander seeds",25],["Cumin",10],["Fennel",5],["Kashmiri chilli",15],["Black pepper",4],["Cinnamon",4],["Cloves",2],["Green cardamom",3],["Bay leaf",2],["Turmeric",5],["Kasuri methi",5],["Dry ginger",3],["Amchur",5],["Nutmeg & mace",1]],"Roast the whole spices lightly, cool, grind, mix with turmeric, ginger and kasuri methi; sieve.","1 tbsp per kg of paneer, mixed veg or kofta gravy.","5 months.",[],"kitchen king masala recipe"],
["sabji","Spice blends","Sabji masala (everyday)","curry","Mild all-purpose dry-curry powder for dry sabjis.",[["Coriander seeds",30],["Cumin",10],["Kashmiri chilli",15],["Turmeric",8],["Fennel",6],["Black pepper",3],["Cinnamon",3],["Cloves",1],["Dry ginger",3],["Amchur",6],["Black salt",2],["Asafoetida",1]],"Roast whole spices, cool, grind with the powders, sieve.","1–2 tsp per ½ kg dry vegetable, added with salt.","4 months.",[],"sabji masala recipe"],
["biryani","Rice & pulao","Veg biryani / pulao masala","biryani","Fragrant whole-spice-forward blend for dum biryani and pulao.",[["Shahi jeera (caraway)",10],["Green cardamom",10],["Black cardamom",6],["Cloves",6],["Cinnamon",12],["Star anise",4],["Mace",3],["Nutmeg",2],["Fennel",8],["Bay leaf",4],["Black pepper",6],["Dried rose petals",5],["Coriander seeds",20],["Kewra powder (optional)",1]],"Roast lightly without browning; cool; grind fine; sieve.","1 tbsp per kg rice; also bloom whole spices in ghee.","6 months.",[],"biryani masala powder recipe"],
["tandoori","Tandoor & grill","Tandoori / tikka masala","tandoori","Red-gold marinade powder for paneer tikka and soya chaap.",[["Kashmiri chilli",25],["Coriander seeds",20],["Cumin",10],["Kasuri methi",6],["Dry ginger",6],["Garlic powder",6],["Amchur",5],["Black pepper",4],["Cinnamon",3],["Cloves",1],["Green cardamom",2],["Turmeric",4],["Black salt",3],["Beetroot powder (colour, optional)",5]],"Roast whole spices lightly; grind with the rest; sieve very fine so it clings to the marinade.","2 tbsp per kg hung-curd marinade with lemon, mustard oil and gram flour.","4 months.",[],"tandoori masala powder recipe"],
["chai","Beverage","Chai masala","chai","Warm-sweet tea spice, ginger-led.",[["Dry ginger powder",30],["Green cardamom",20],["Cinnamon",15],["Cloves",8],["Black pepper",8],["Fennel",8],["Nutmeg",2],["Tulsi/basil, dried (optional)",5]],"Lightly warm the whole spices, cool, grind fine with ginger powder; sieve.","¼ tsp per cup of tea, boiled with the leaves.","6 months.",[],"chai masala powder recipe"],
["jaljeera","Beverage","Jaljeera powder","jal","Cooling, minty-tangy digestive drink mix.",[["Cumin, roasted",25],["Amchur",20],["Black salt",12],["Dried mint (pudina)",12],["Dry ginger",5],["Black pepper",5],["Sugar, powdered",15],["Citric acid / dried lemon",3],["Asafoetida",1]],"Roast cumin and pepper; cool; grind everything to a fine powder; keep dry.","1½ tsp per glass of chilled water with boondi and lemon.","4 months; keep spoons dry.",["PePgIVmZW9s","ODxuy0i1cYE"],"jaljeera powder recipe"],
["panch","Bengali","Panch phoron (Bengali five-spice)","panch","Whole-seed tempering mix: equal parts of five seeds.",[["Cumin",20],["Fennel",20],["Nigella (kalonji)",20],["Fenugreek seed",20],["Brown mustard / radhuni",20]],"Just mix; no grinding. Crackle in hot mustard oil for 10 seconds before adding vegetables.","Bengali dals, shukto, aloo posto, chorchori, chutneys.","1 year airtight.",["lXgWdYE9d0A","esMzRz4zVgg"],"panch phoron recipe"],
["gorom","Bengali","Gorom moshla (Bengali garam masala)","garam","Three whole spices only – sweet and clean, not heavy.",[["Green cardamom",35],["Cinnamon",40],["Cloves",25]],"Dry-roast 1 min, cool, grind to a fine powder (or use whole in the oil).","Finish alu dum, polao, kosha, dalna and payesh.","6 months.",["ien9Lg0ilxo","RDPniAXiHco"],"bengali gorom moshla recipe"],
["goda","Maharashtrian","Goda masala","chole","Dark, sweetish Maharashtrian blend with dry coconut and stone-flower.",[["Coriander seeds",30],["Cumin",10],["Dry coconut, grated",15],["Sesame",8],["Cinnamon",5],["Cloves",3],["Black pepper",3],["Bay leaf",3],["Shahi jeera",5],["Stone flower (dagad phool)",3],["Dry red chilli",8],["Asafoetida & turmeric",3]],"Roast each ingredient separately till dark and aromatic; coconut last until brown; cool; grind fine.","Usal, bharli vangi, masale bhat, amti.","3–4 months (coconut).",["Rql0Yh1SHgg","1H05c294M5w"],"goda masala recipe"],
["dabeli","Street & snack","Dabeli masala (Kutchi)","dabeli","Sweet-tangy-spicy filling mix for Kutchi dabeli.",[["Coriander seeds",25],["Cumin",8],["Dry coconut",15],["Kashmiri chilli",12],["Cinnamon",5],["Cloves",3],["Fennel",8],["Sesame",5],["Black pepper",3],["Sugar",8],["Black salt",4],["Amchur",4]],"Roast spices and coconut separately, cool, grind fine with sugar and salt.","2 tbsp per ½ kg boiled potato filling with tamarind chutney, peanuts, pomegranate.","3 months.",["_HyXbnf4R_8","bBJ311c6Z0Q"],"dabeli masala recipe"],
["currypowder","Spice blends","Curry powder (mild, general)","curry","Yellow all-purpose curry powder for quick gravies and soups.",[["Coriander seeds",30],["Cumin",12],["Turmeric",18],["Fenugreek seed",4],["Mustard",3],["Fennel",5],["Black pepper",5],["Kashmiri chilli",12],["Cinnamon",3],["Dry ginger",5],["Cardamom",3]],"Roast whole spices lightly; cool; grind with turmeric and ginger; sieve.","1–2 tsp per litre of gravy, soup or vegetable stew.","4 months.",["ruFIqLbCXsE","uHPRiiWUsxA"],"indian curry powder recipe"],
["rajma","Punjabi","Rajma masala","chole","Earthy, deep red masala for rajma chawal.",[["Coriander seeds",30],["Cumin",12],["Kashmiri chilli",18],["Black pepper",4],["Cinnamon",5],["Bay leaf",3],["Black cardamom",4],["Cloves",3],["Dry ginger",4],["Kasuri methi",5],["Amchur",6],["Black salt",3]],"Roast whole spices; cool; grind with powders; sieve.","2 tbsp per kg boiled rajma, simmer 20 min.","5 months.",["-Mc-UqmTT-g","y7xxMUL7_9g"],"rajma masala powder recipe"],
["bisibele","South Indian","Bisi bele bath powder","bisi","Karnataka rice-lentil-vegetable masala with coconut and marathi mogga.",[["Dried red chilli (byadgi)",20],["Coriander seeds",25],["Chana dal",8],["Urad dal",5],["Dry coconut",12],["Cumin",4],["Fenugreek",2],["Cinnamon",5],["Cloves",3],["Marathi mogga (kapok bud)",2],["Poppy seed",4],["Curry leaves, dried",5],["Asafoetida",1]],"Roast dals and spices separately in a little ghee; roast coconut last; cool; grind fine.","3 tbsp per 2 cups rice-dal; finish with ghee, boondi and cashews.","2–3 months.",["VEArdyBWvdw","aPVr_9aZq2c"],"bisi bele bath powder recipe"],
["thandai","Beverage","Thandai masala","thandai","Cooling nut-and-seed milk spice (festival drink).",[["Almonds",25],["Pistachio",10],["Melon seeds (magaz)",12],["Poppy seeds",8],["Fennel",10],["Green cardamom",5],["Black pepper",3],["Rose petals, dried",5],["Saffron strands",0.3],["Sugar, powdered",20]],"Dry-roast seeds and fennel lightly; cool; grind with nuts to a fine powder; mix with sugar and saffron.","3 tbsp per 500 ml hot or chilled milk.","2–3 months in the fridge (nuts).",["d11212_jFPw","PJCuk5hWLiQ"],"thandai masala powder recipe"],
["amchurchutney","Spice blends","Dry spice for kadhi / tadka","kadhi","Punjabi-style tadka blend for kadhi and dal fry.",[["Cumin",30],["Fenugreek seed",10],["Mustard seed",15],["Dry red chilli, broken",20],["Curry leaves, dried",10],["Asafoetida",5],["Ajwain",10]],"Mix whole; use directly in hot ghee as tempering.","Kadhi pakora, dal fry, dhokla tadka.","3 months.",[],"kadhi tadka masala"],
["pahadi","Spice blends","Pahadi namak (Uttarakhand pisu loon)","paste","Hand-ground hill salt with green garlic, chilli and mint – a fresh, fiery table salt.",[["Rock salt (coarse)",50],["Green garlic leaves / spring garlic",30],["Green chilli",8],["Fresh mint (pudina)",6],["Fresh coriander leaves",6],["Roasted cumin",4],["Roasted coriander seed",3],["Lemon juice",5]],"Chop the greens finely. Traditionally crush salt, chilli and cumin on a stone (sil-batta) first, then grind in the garlic, herbs and lemon till a moist, coarse green salt forms. Sun-dry 1 day or rest in the fridge for flavour to mingle.","Sprinkle on cucumber, radish, fruit, boiled corn, roasted peanuts, parathas; stir into curd or buttermilk.","1 week fridge; sun-dried version 1 month in an airtight jar.",["4cRL6UFoNaQ","IOrJgb-ZKnc"],"pahadi namak recipe"],
["gg","Gravy bases & pastes","Ginger-garlic paste","paste","Daily base paste; ratio 1:1 for sabji, 2:1 garlic:ginger for gravy depth.",[["Ginger, peeled",500],["Garlic, peeled",500],["Neutral oil",30],["Salt",20]],"Blend with oil and salt to a fine paste; freeze in flat bags or ice-cubes.","1 tsp per 250 g vegetables; 1 tbsp per litre of gravy.","1 week fridge, 3 months freezer.",["9x5Bb4KzMqM","i2NomaSxKX0"],"ginger garlic paste recipe"],
["redgravy","Gravy bases & pastes","Basic red gravy (onion-tomato)","kadhi","Workhorse base for kadai, bhuna, masala and handi gravies.",[["Onion, chopped (kg-wise)",1000],["Tomato (g)",1000],["Ginger-garlic paste",100],["Oil/ghee",120],["Salt",20],["Whole spices (bay, cardamom, cloves, cinnamon)",5],["Kashmiri chilli powder",15]],"Sauté whole spices, onions golden, add paste and tomato; cook till oil separates; cool; blend smooth. Portion and freeze.","200 ml per portion with ½ kg vegetables or paneer plus finishing spices.","3 days fridge, 3 months freezer.",["fWe8Pi-4U00","Z7CZDpOLnQk"],"basic onion tomato gravy"],
["makhani","Gravy bases & pastes","Makhani gravy","dal","Creamy tomato-butter base for paneer butter masala, dal makhani, kofta.",[["Tomato (g)",1500],["Butter",100],["Cashew",80],["Ginger-garlic paste",60],["Kashmiri chilli",15],["Sugar",20],["Cream",150],["Kasuri methi",5],["Salt",25]],"Boil tomatoes with cashew and spices; blend, strain; simmer in butter; finish with cream, sugar, kasuri methi.","150 ml per portion; add paneer cubes or boiled dal.","3 days fridge, 2 months freezer (add cream fresh).",["rlqNDoNMd6E","hhUyN1KSg-8"],"makhani gravy base"],
["white","Gravy bases & pastes","White gravy (cashew-onion)","shahi","Pale, rich base for shahi paneer, korma, malai kofta.",[["Onion, boiled (g)",1000],["Cashew",150],["Melon seed",50],["Green chilli",20],["Ginger paste",30],["Cream/milk",100],["White pepper",3],["Salt",20]],"Boil onions, cashew and melon seeds with chilli and ginger; blend fine; cook in ghee without browning; finish with cream.","150 ml per portion with paneer, vegetables, kofta.","2 days fridge, 2 months freezer.",["3QYB3q362aQ","RhhOGT-OjGA"],"white gravy base"],
["green","Gravy bases & pastes","Green gravy (palak-coriander)","palak","Bright base for palak paneer, hara bhara, green kofta.",[["Spinach, blanched (g)",1000],["Coriander leaves",100],["Green chilli",30],["Garlic",40],["Ginger",30],["Onion",300],["Oil",80],["Salt",20]],"Blanch spinach 2 min, ice-shock, blend with coriander and chilli; sauté onion-garlic; combine; cook 5 min only to keep colour.","150 ml per portion with paneer, matar or corn.","2 days fridge, 2 months freezer (squeezed).",["OkDU9vmQtow","VSCKBYMmsZo"],"green gravy spinach base"]
